INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload) VALUES('core-2026-09-v3','demonstratives','e49c6c64b6333354230b05b223ded19e0e7519c1828bf3f36aee778f9f3f39c4','{"slug":"demonstratives","title":"This, that, these and those","level":"A1","order":5,"summary":"Choose words that point to things and distinguish number from distance.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Near and far","Plural demonstratives","Pointing without a following noun","Referring to ideas and time"],"rules":[{"title":"Near and far","explanation":"Use **this** for one nearby thing and **that** for one more distant thing. Distance can be physical or part of how the speaker views a situation. Demonstratives can stand alone or come before a noun.","pattern":"**This** seat is free. / **That** seat by the door is taken.","commonMistakes":["This and that are singular, even when the object seems large or contains many parts."],"examples":["Point to one book in your hand: “**This** book is mine.”","Point to one box in your hand: “**This** box is mine.”"],"skill":"form"},{"title":"Plural demonstratives","explanation":"Use **these** for nearby plural things and **those** for more distant plural things. Match the following noun and verb to plural number. Near and far are described explicitly in the practice so that the intended choice is clear.","pattern":"**These books are** mine. / **Those books are** yours.","commonMistakes":["These is pronounced differently from this. In writing, remember the final -e in these."],"examples":["Point to one book far away across the room: “**That** book is yours.”","Point to one box far away across the room: “**That** box is yours.”"],"skill":"meaning"},{"title":"Pointing without a following noun","explanation":"A demonstrative can function as a pronoun when the thing is already understood. It still has number: This is mine; These are mine. Do not add an unnecessary noun merely because the demonstrative has no following noun.","pattern":"What is **that**? / Who owns **these**?","commonMistakes":["The word it refers back to an identified thing but does not make the same near/far contrast."],"examples":["Point to several books beside you: “**These** books are ours.”","Point to several boxes beside you: “**These** boxes are ours.”"],"skill":"contrast"},{"title":"Referring to ideas and time","explanation":"This and that can refer to an event or whole idea. This week identifies the current week; that week points to a week already identified elsewhere. In conversation, that often responds to something just said.","pattern":"The train was cancelled. **That** was frustrating.","commonMistakes":["Real conversational choices depend on viewpoint. The questions here use explicit physical distance rather than judging subjective emphasis."],"examples":["Point to several books far away beyond the fence: “**Those** books are theirs.”","Point to several boxes far away beyond the fence: “**Those** boxes are theirs.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"quizItems":[{"id":"3e5b1bcc-9fcb-503a-a6d5-0b90f124c8d5","topicSlug":"demonstratives","level":"A1","prompt":"Point to one book in your hand: “____ book is mine.”","choices":[{"id":"A","text":"That"},{"id":"B","text":"These"},{"id":"C","text":"Those"},{"id":"D","text":"This"}],"answerId":"D","hint":"Check two features: **one** item and **near** the speaker.","explanation":"One nearby item takes **this**.","keywords":["near-singular"],"skill":"near-singular","contextKey":"demonstratives-1","fingerprint":"dcec911d402f6d31b3fd000d7ed47d808795eb5ab479bd9b0b714da20f3103b8","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check two features: **one** item and **near** the speaker.","One nearby item takes **this**.","Choose **This**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That points away from the speaker; the item is explicitly in your hand.","B":"These is plural.","C":"Those is both plural and distant.","D":"One nearby item takes **this**."}}},{"id":"daf0de56-b650-5a40-aa78-321dcf5f67f5","topicSlug":"demonstratives","level":"A1","prompt":"Point to one book far away across the room: “____ book is yours.”","choices":[{"id":"A","text":"These"},{"id":"B","text":"Those"},{"id":"C","text":"That"},{"id":"D","text":"This"}],"answerId":"C","hint":"Check **one + distant**.","explanation":"One distant item takes **that**.","keywords":["far-singular"],"skill":"far-singular","contextKey":"demonstratives-1","fingerprint":"8337b9ee3e0e01f0b6c5ef7a24346a26d083096d6eee3bb1edd165d81e55f058","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check **one + distant**.","One distant item takes **that**.","Choose **That**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"These is plural and near.","B":"Those is plural, but the task says one.","C":"One distant item takes **that**.","D":"This points to something near; the task explicitly places it far away."}}},{"id":"537d56e3-ec85-5f3b-a4fe-e94cc0f07b63","topicSlug":"demonstratives","level":"A1","prompt":"Point to several books beside you: “____ books are ours.”","choices":[{"id":"A","text":"That"},{"id":"B","text":"Those"},{"id":"C","text":"These"},{"id":"D","text":"This"}],"answerId":"C","hint":"Check **several + nearby**.","explanation":"Nearby plural things take **these**.","keywords":["near-plural"],"skill":"near-plural","contextKey":"demonstratives-1","fingerprint":"2b45fd363dfbfc6907f86cdc2196a94ec04c38b5e3d90d532710d79a380c910a","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check **several + nearby**.","Nearby plural things take **these**.","Choose **These**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That is singular and distant.","B":"Those is plural but distant; these things are beside you.","C":"Nearby plural things take **these**.","D":"This is singular."}}},{"id":"61cf2633-a88f-5e98-a050-bb132625b389","topicSlug":"demonstratives","level":"A1","prompt":"Point to several books far away beyond the fence: “____ books are theirs.”","choices":[{"id":"A","text":"That"},{"id":"B","text":"These"},{"id":"C","text":"Those"},{"id":"D","text":"This"}],"answerId":"C","hint":"Check **several + distant**.","explanation":"Distant plural things take **those**.","keywords":["far-plural"],"skill":"far-plural","contextKey":"demonstratives-1","fingerprint":"233a33402877f5635d44a22537b3ae45597a776b8b2a4fe39205407819e7fbde","source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["bc-determiners"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"teaching":{"steps":["Check **several + distant**.","Distant plural things take **those**.","Choose **Those**. Read the complete sentence again and check both its form and its intended meaning."],"choiceReasons":{"A":"That is distant but singular.","B":"These is plural but near.","C":"Distant plural things take **those**.","D":"This is singular and near."}}},{"id":"7363a269-3851-5f89-ab96-b1b70258f486","topicSlug":"demonstratives","level":"A1","prompt":"Point to one box in your hand: “____ box is mine.”